const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s);
const toast=message=>{const node=$('#toast');if(!node)return;node.textContent=message;node.classList.add('show');setTimeout(()=>node.classList.remove('show'),3000)};
let activeView='twin',activeDetail=null,botMode='eco',projectorFailure=false;
function setTopbarTheme(mode){document.body.classList.remove('context-connect','context-eco','context-twin');document.body.classList.add(mode==='connect'?'context-connect':mode==='eco'?'context-eco':'context-twin');}
function showView(id){$$('.view').forEach(x=>x.classList.remove('active'));$$('.detail-page').forEach(x=>x.classList.remove('active'));$('#connect-operation-panel')?.setAttribute('hidden','');const target=$('#'+id);if(target)target.classList.add('active');activeView=id;activeDetail=null;$('.switcher')?.classList.toggle('eco',id==='eco');$('.switcher')?.classList.toggle('none',!['connect','eco'].includes(id));$$('.switcher button').forEach(x=>x.classList.toggle('active',x.dataset.view===id));setTopbarTheme(id==='connect'?'connect':id==='eco'?'eco':'twin');syncBotVisibility();window.scrollTo({top:0,behavior:'smooth'});}
function showDetail(id){$$('.view').forEach(x=>x.classList.remove('active'));$$('.detail-page').forEach(x=>x.classList.remove('active'));if(id==='operations'){openOperation('optimizer');return;}const target=$('#'+id);if(target)target.classList.add('active');activeDetail=id;setTopbarTheme(['c-dashboard','c-map','c-insights','c-report'].includes(id)?'connect':'eco');syncBotVisibility();window.scrollTo({top:0,behavior:'smooth'});if(id==='c-dashboard')loadConnectDashboard();}
