$$('[data-connect-page]').forEach(x=>x.onclick=()=>{showDetail(x.dataset.connectPage);$('#connect-links')?.classList.remove('open')});
$$('.back').forEach(x=>x.onclick=()=>showView(['operations','c-dashboard','c-map','c-insights','c-report'].includes(activeDetail)?'connect':'eco'));
