function saveLocalOp(key,value){localOps[key]=value;localStorage.setItem('campusTwinOps',JSON.stringify(localOps));}
const escOp=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
