let roomDirectory=[...roomSeed,...(localOps.rooms||[])],activeRoomCategory='All';
const statusClass=s=>String(s||'').toLowerCase()==='attention'?'watch':String(s||'').toLowerCase()==='unavailable'?'critical':String(s||'').toLowerCase()==='empty'?'empty':'stable';
function roomCard(r){return `<article class="room-card ${statusClass(r.status)}"><div class="room-card-head"><div><span class="room-code">${escOp(r.room_number)}</span><h3>${escOp(r.room_name)}</h3><small>${escOp(r.category)} · 1st</small></div><b class="room-status">${escOp(r.status)}</b></div><div class="room-grid"><div><span>Seats</span><b>${escOp(r.capacity)}</b></div><div><span>Occupied</span><b>${escOp(r.occupied_seats)}</b></div><div><span>Benches</span><b>${escOp(r.benches)}</b></div><div><span>Projector</span><b>${escOp(r.projector)}</b></div><div><span>Board</span><b>${escOp(r.board)}</b></div><div><span>Network</span><b>${escOp(r.network)}</b></div></div><div class="room-resources">Resources: ${escOp(r.resources||'—')}</div><div class="room-card-actions"><button class="room-open" data-room="${escOp(r.room_number)}">View details →</button><button class="room-edit" data-edit-room="${escOp(r.room_number)}">Edit</button></div></article>`;}
function renderRooms(){const host=$('#c-room-grid');if(!host)return;const q=($('#c-room-search')?.value||'').trim().toLowerCase(),cat=activeRoomCategory;const filtered=roomDirectory.filter(r=>(!q||`${r.room_number} ${r.room_name}`.toLowerCase().includes(q))&&(cat==='All'||r.category===cat));host.innerHTML=filtered.map(roomCard).join('')||'<div class="rooms-empty">No spaces match the current filters.</div>';bindRoomButtons();const count={available:0,attention:0,unavailable:0,empty:0};roomDirectory.forEach(r=>count[String(r.status||'').toLowerCase()]++);['available','attention','unavailable','empty'].forEach(k=>{const n=$('#c-room-'+k);if(n)n.textContent=count[k]||0});const seats=roomDirectory.reduce((a,r)=>a+Number(r.capacity||0),0);const occupied=roomDirectory.reduce((a,r)=>a+Number(r.occupied_seats||0),0);if($('#c-room-seats'))$('#c-room-seats').textContent=seats;if($('#c-room-total'))$('#c-room-total').textContent=roomDirectory.length;}
function bindRoomButtons(){$$('[data-room]').forEach(x=>x.onclick=()=>{const key=x.dataset.room;const r=roomDirectory.find(v=>v.room_number===key)||roomDirectory.find(v=>v.room_name===key);const detail=$('#c-room-detail');if(detail&&r){detail.innerHTML=`<b>${escOp(r.room_number)} · ${escOp(r.room_name)}</b><p>${escOp(r.category)} · capacity ${escOp(r.capacity)} · occupied ${escOp(r.occupied_seats)} · status ${escOp(r.status)}.</p><p>Equipment: ${escOp(r.projector)}, ${escOp(r.board)}, ${escOp(r.network)}. Recommended next action: ${r.status==='Attention'?'Open a maintenance check.':r.status==='Unavailable'?'Keep out of booking until cleared.':'Use this room for the next compatible allocation.'}</p>`;detail.scrollIntoView({behavior:'smooth',block:'center'});}else toast(`${key} selected.`);});}
async function tryApi(url,opts={}){const r=await fetch(url,{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Server update failed');return data;}
function renderLocalRooms(){const rooms=localOps.rooms||[];return rooms.length?`<table class="operation-table"><thead><tr><th>Room</th><th>Type</th><th>Capacity</th><th>Status</th></tr></thead><tbody>${rooms.map(r=>`<tr><td>${escOp(r.name)}</td><td>${escOp(r.type)}</td><td>${escOp(r.capacity)}</td><td>${escOp(r.status)}</td></tr>`).join('')}</tbody></table>`:'No local resource records yet.';}
function issueCard(i){return `<article class="issue-card ${String(i.priority||'Medium').toLowerCase()}"><div class="issue-main"><div class="issue-top"><span class="priority-pill">${escOp(i.priority||'Medium')}</span><span class="issue-status">${escOp(i.status||'Open')}</span></div><h3>${escOp(i.title||'Reported issue')}</h3><p>${escOp(i.description||'No description supplied.')}</p><div class="issue-meta"><span>${escOp(i.category||'General')} · ${escOp(i.status||'Open')}</span></div></div><b class="issue-room">${escOp(i.rooms?.room_number||i.location||'Campus')}</b></article>`;}
async function loadIssues(){const out=$('#c-issue-list');if(!out)return;try{const data=await tryApi('/api/issues');out.innerHTML=(data||[]).map(issueCard).join('')||'<div class="operation-note">No maintenance issues are currently recorded.</div>';}catch(err){out.innerHTML='<div class="operation-note">Live issue queue unavailable. Use the form below to create a browser-local maintenance record.</div>';}}
function opShell(d,body){return `<div class="operation-head"><span>${d.icon}</span><div><h3>${d.title}</h3><p>${d.intro}</p></div></div>${body}`;}
function openOperation(key){const k=key||'optimizer',d=operation[k];$$('.operation-nav-grid button').forEach(b=>b.classList.toggle('active',b.dataset.operation===k));let body='';
if(k==='optimizer')body=`<form class="operation-form" data-op-form="optimizer"><label>Students<input name="students" type="number" min="1" required value="${localOps.optimizer?.students||30}"></label><label>Day<select name="day"><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option></select></label><label>Start time<input name="start_time" type="time" required value="${localOps.optimizer?.start_time||'09:00'}"></label><label>End time<input name="end_time" type="time" required value="${localOps.optimizer?.end_time||'10:00'}"></label><label>Projector<select name="projector"><option value="">Not required</option><option value="true">Required</option></select></label><label>Network<select name="network"><option value="">Not required</option><option value="true">Required</option></select></label><label>Board<select name="board"><option value="">Not required</option><option value="true">Required</option></select></label><button class="primary azure" type="submit">✦ Find best-fit rooms</button></form><div id="optimizer-result" class="operation-note">Enter the class requirements and run the optimizer.</div><button type="button" class="ai-inline-button" data-ai-explain="optimizer">✦ Hybrid AI explanation</button><div id="optimizer-ai-panel" class="inline-ai-panel" hidden></div>`;
if(k==='rooms')body=`<div class="rooms-toolbar"><div class="room-search"><span>⌕</span><input id="c-room-search" placeholder="Search room number or name"></div><div class="room-filters"><button class="selected" data-room-filter="All">All</button><button data-room-filter="Classroom">Classroom</button><button data-room-filter="Laboratory">Laboratory</button><button data-room-filter="Staff Room">Staff Room</button><button data-room-filter="HOD Room">HOD Room</button><button data-room-filter="Seminar Hall">Seminar Hall</button><button data-room-filter="Toilet">Toilet</button><button data-room-filter="Other">Other</button></div><button type="button" data-add-room class="room-add">＋ Add room</button></div><div class="room-summary"><span><b id="c-room-total">12</b> Rooms</span><span><b id="c-room-available">8</b> Available</span><span><b id="c-room-attention">2</b> Attention</span><span><b id="c-room-unavailable">1</b> Unavailable</span><span><b id="c-room-empty">1</b> Empty</span><span><b id="c-room-seats">585</b> Seats</span></div><div id="c-room-grid" class="room-grid-list"></div><div class="operation-actions"><button type="button" data-load-rooms>↻ Refresh live room data</button></div>`;
if(k==='maintenance')body=`<div class="issue-toolbar"><div><b>Maintenance queue</b><span>Track issues from report to repair and faculty verification.</span></div><button type="button" data-refresh-issues>↻ Refresh</button></div><div id="c-issue-list" class="issue-list-dashboard"></div><form class="operation-form" data-op-form="maintenance"><label>Location<input name="location" required value="${localOps.maintenance?.location||'CSE-103'}"></label><label>Priority<select name="priority"><option>Low</option><option>Medium</option><option selected>High</option><option>Critical</option></select></label><label>Issue title<input name="title" required value="${localOps.maintenance?.title||''}" placeholder="Projector has no display"></label><label>Category<select name="category"><option>Equipment</option><option>Network</option><option>Electrical</option><option>Plumbing</option><option>Safety</option><option>Other</option></select></label><label class="full">Description<textarea name="description" required placeholder="Describe the issue and the expected action.">${localOps.maintenance?.description||''}</textarea></label><label>Status<select name="status"><option>Open</option><option>In Progress</option><option>Resolved</option></select></label><label>Worker note<input name="worker_note" value="${localOps.maintenance?.worker_note||''}" placeholder="Inspection or repair note"></label><button class="primary azure" type="submit">⚑ Save maintenance update</button></form><div id="maintenance-result" class="operation-note">Updates are retained locally and can be synced through the maintenance API for authorized sessions.</div>`;
if(k==='timetable')body=`<form class="operation-form" data-op-form="timetable"><label>Day<select name="day"><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option></select></label><label>Section<input name="section" required value="${localOps.timetable?.section||'CSE-A'}"></label><label>Start time<input name="start_time" type="time" required value="${localOps.timetable?.start_time||'09:00'}"></label><label>End time<input name="end_time" type="time" required value="${localOps.timetable?.end_time||'09:50'}"></label><label>Room<input name="room" required value="${localOps.timetable?.room||'CSE-101'}"></label><label>Subject<input name="subject" required value="${localOps.timetable?.subject||'Data Structures'}"></label><button class="primary azure" type="submit">◫ Save clash-free entry</button></form><div class="timetable-preview"><b>Weekly sheet</b><div class="time-slots"><span>09:00–09:50</span><span>09:50–10:40</span><span>10:50–11:40</span><span>11:40–12:30</span><span>13:30–14:20</span><span>14:20–15:10</span><span>15:10–16:00</span><span>16:00–16:50</span></div><p>Saved classes will appear in the teaching sheet and are checked for local room overlap before saving.</p></div><div id="timetable-result" class="operation-note">The local flow blocks overlapping room entries.</div>`;
if(k==='progress')body=`<div class="progress-summary"><span><b id="c-progress-subjects">0</b> Subjects tracked</span><span><b id="c-progress-average">0%</b> Avg coverage</span><span><b id="c-progress-completed">0</b> Completed</span><span><b id="c-progress-updates">0</b> Weekly updates</span></div><form class="operation-form" data-op-form="progress"><label>Subject code<input name="code" required value="${localOps.progress?.code||'CS301'}"></label><label>Week number<input name="week_number" type="number" min="1" max="30" required value="${localOps.progress?.week_number||8}"></label><label>Coverage %<input name="coverage_percent" type="number" min="0" max="100" required value="${localOps.progress?.coverage_percent||72}"></label><label>Credits<input name="credits" type="number" min="1" step="0.5" value="${localOps.progress?.credits||4}"></label><label class="full">Topics covered<textarea name="topics_covered" required>${localOps.progress?.topics_covered||'Arrays, linked lists, stacks and queues completed.'}</textarea></label><button class="primary azure" type="submit">⌁ Save syllabus update</button></form><div id="progress-result" class="operation-note">Coverage is saved locally immediately.</div>`;
if(activeDetail||!$('#connect')?.classList.contains('active'))showView('connect');if($('#operation-title'))$('#operation-title').textContent=d.title;if($('#operation-content'))$('#operation-content').innerHTML=opShell(d,body);const panel=$('#connect-operation-panel'),content=$('#connect-operation-content');if(panel&&content){content.innerHTML=opShell(d,body);panel.hidden=false;panel.classList.add('open');setTopbarTheme('connect');syncBotVisibility();setTimeout(()=>panel.scrollIntoView({behavior:'smooth',block:'start'}),20);}if(k==='rooms'){renderRooms();}if(k==='maintenance'){loadIssues();}if(k==='progress'){loadProgressSummary();}}
