document.addEventListener('input',e=>{if(e.target.id==='c-room-search')renderRooms();});
$$('[data-open="operations"]').forEach(x=>x.onclick=()=>openOperation('optimizer'));

document.addEventListener('submit',async e=>{const form=e.target.closest('[data-op-form]');if(!form)return;e.preventDefault();const key=form.dataset.op,data=Object.fromEntries(new FormData(form));saveLocalOp(key,data);const out=$(`#${key}-result`);try{if(key==='optimizer'){const payload={...data,students:Number(data.students),projector:!!data.projector,network:!!data.network,board:!!data.board};const d=await tryApi('/api/optimizer',{method:'POST',body:JSON.stringify(payload)});out.innerHTML=d.recommendations?.length?`<b>${escOp(d.analysis)}</b><ul>${d.recommendations.map(r=>`<li><b>${escOp(r.room_number)} · ${escOp(r.room_name)}</b> — score ${escOp(r.score)}. ${r.reasons.map(escOp).join(' · ')}</li>`).join('')}</ul>`:'No matching rooms found.';}else if(key==='maintenance'){out.textContent='Maintenance update saved locally. Authorized live sync can be applied from the repair workflow.';loadIssues();}else if(key==='timetable'){const entries=JSON.parse(localStorage.getItem('campusTwinTimetable')||'[]');const clash=entries.some(x=>x.day===data.day&&x.room===data.room&&x.start_time<data.end_time&&x.end_time>data.start_time);if(clash){out.textContent='Clash detected: that room already has an overlapping local entry.';return}entries.push(data);localStorage.setItem('campusTwinTimetable',JSON.stringify(entries));out.innerHTML=`<b>Saved.</b> ${escOp(data.day)} ${escOp(data.start_time)}–${escOp(data.end_time)} · ${escOp(data.subject)} · ${escOp(data.room)}.`;}else if(key==='progress'){out.innerHTML=`<b>Saved.</b> ${escOp(data.code)} is now ${escOp(data.coverage_percent)}% covered for week ${escOp(data.week_number)}.`;loadProgressSummary();}}catch(err){out.innerHTML=`<b>Local save complete.</b> Live sync is unavailable: ${escOp(err.message)}`;}});

document.addEventListener('click',async e=>{if(e.target.closest('[data-room-filter]')){const b=e.target.closest('[data-room-filter]');activeRoomCategory=b.dataset.roomFilter;$$('[data-room-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderRooms();}if(e.target.closest('[data-room]')&&$('#c-room-grid')){const key=e.target.closest('[data-room]').dataset.room;const r=roomDirectory.find(v=>v.room_number===key)||roomDirectory.find(v=>v.room_name===key);if(r)showRoomDetail(r);}if(e.target.closest('[data-add-room]')){openRoomDialog();}if(e.target.closest('[data-edit-room]')){const key=e.target.closest('[data-edit-room]').dataset.editRoom;const r=roomDirectory.find(v=>v.room_number===key);if(r)openRoomDialog(r);}if(e.target.closest('[data-load-rooms]')){try{const data=await tryApi('/api/rooms');roomDirectory=data;toast('Live room directory loaded.');renderRooms();}catch(err){toast('Live room directory unavailable; showing demo records.');renderRooms();}}if(e.target.closest('[data-refresh-issues]'))loadIssues();});
$('#room-add-dialog')?.addEventListener('click',e=>{if(e.target.id==='room-add-dialog')e.target.close();});
$('.room-dialog-close')?.addEventListener('click',()=>$('#room-add-dialog')?.close());
$('.room-dialog-cancel')?.addEventListener('click',()=>$('#room-add-dialog')?.close());
function openRoomDialog(room=null){const form=$('#room-add-form'),dialog=$('#room-add-dialog');if(!form||!dialog)return;form.reset();form.querySelector('[name=editing_room_number]').value=room?.room_number||'';$('#room-dialog-title').textContent=room?'Edit room':'Add a room';const values={room_number:room?.room_number||'',room_name:room?.room_name||'',category:room?.category||'Classroom',capacity:room?.capacity??30,occupied_seats:room?.occupied_seats??0,benches:room?.benches??15,projector:room?.projector||'Available',board:room?.board||'Smart Board',network:room?.network||'Available',status:room?.status||'Available',resources:room?.resources||''};Object.entries(values).forEach(([k,v])=>{const el=form.elements[k];if(el)el.value=v;});$('#room-dialog-submit').textContent=room?'Save changes':'＋ Add room';dialog.showModal();}
$('#room-add-form')?.addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const editing=data.editing_room_number;delete data.editing_room_number;data.capacity=Number(data.capacity||0);data.occupied_seats=Number(data.occupied_seats||0);data.benches=Number(data.benches||0);const record={...data};const localRooms=localOps.rooms||[];const oldIndex=localRooms.findIndex(r=>r.room_number===editing);if(oldIndex>=0)localRooms[oldIndex]=record;else localRooms.push(record);saveLocalOp('rooms',localRooms);const idx=roomDirectory.findIndex(r=>r.room_number===editing||r.room_number===record.room_number);if(idx>=0)roomDirectory[idx]=record;else roomDirectory.push(record);e.target.reset();$('#room-add-dialog')?.close();toast(`${record.room_number} · ${editing?'updated':'added'} successfully.`);renderRooms();});
function showRoomDetail(r){const detail=$('#c-room-detail');if(detail){detail.innerHTML=`<b>${escOp(r.room_number)} · ${escOp(r.room_name)}</b><p>${escOp(r.category)} · capacity ${escOp(r.capacity)} · occupied ${escOp(r.occupied_seats)} · status ${escOp(r.status)}.</p><p>Equipment: ${escOp(r.projector)}, ${escOp(r.board)}, ${escOp(r.network)}. Recommended next action: ${r.status==='Attention'?'Open a maintenance check.':r.status==='Unavailable'?'Keep out of booking until cleared.':'Use this room for the next compatible allocation.'}</p>`;detail.scrollIntoView({behavior:'smooth',block:'center'});}else toast(`${r.room_name} — ${r.status}`);}

const chartPoints=(values)=>values.map((v,i)=>`${Math.round(i*(640/(values.length-1)))},${v}`).join(' ');
