async function loadProgressSummary(){try{const d=await tryApi('/api/progress');const rows=d||[];const avg=rows.length?Math.round(rows.reduce((a,r)=>a+Number(r.coverage_percent||0),0)/rows.length):0;const done=rows.filter(r=>Number(r.coverage_percent||0)>=100).length;if($('#c-progress-subjects'))$('#c-progress-subjects').textContent=new Set(rows.map(r=>r.subject_id||r.code)).size;if($('#c-progress-average'))$('#c-progress-average').textContent=`${avg}%`;if($('#c-progress-completed'))$('#c-progress-completed').textContent=done;if($('#c-progress-updates'))$('#c-progress-updates').textContent=rows.length;if($('#c-coverage-value'))$('#c-coverage-value').textContent=`${avg}%`;}catch(err){}}
