function showConnectMapRoom(name){const r=cMapDirectory[name],out=$('#c-room-detail');if(!r||!out)return;const cls=r.status==='Critical'?'critical':r.status==='Watch'?'watch':'stable';out.innerHTML=`<div class="room-detail-head"><div><span class="room-detail-kicker">${escOp(r.category)}</span><b>${escOp(r.name)}</b></div><span class="room-detail-status ${cls}">${escOp(r.status)}</span></div><div class="room-detail-grid"><span>Capacity<strong>${escOp(r.capacity)}</strong></span><span>Occupied<strong>${escOp(r.occupied)}</strong></span><span>Equipment<strong>${escOp(r.equipment)}</strong></span></div><p>Recommended next action: ${escOp(r.action)}</p>`;$$('.c-big-map [data-room]').forEach(b=>b.classList.toggle('selected',b.dataset.room===name));}
