$('#c-report-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));saveLocalOp('maintenance',{...data,title:'Reported issue',category:'Other',status:'Open'});try{const session=await tryApi('/api/session');const profile=session?.profile||session?.user||session;if(profile?.role==='faculty'&&profile?.id){const rooms=await tryApi('/api/rooms');const room=rooms.find(r=>r.room_number===data.location);if(!room?.id)throw Error('Room record not found');await tryApi('/api/issues',{method:'POST',body:JSON.stringify({room_id:room.id,title:'Reported issue',category:'Other',priority:data.priority,description:data.description})});}toast('Issue reported. The maintenance desk has been notified.');}catch(err){toast('Issue reported locally. Live sync will run after faculty access is available.');}e.target.reset();});
$('.signin').onclick=()=>$('#access').showModal();$('.close').onclick=()=>$('#access').close();$$('[data-role]').forEach(x=>x.onclick=()=>{const isTeam=x.dataset.role.includes('Faculty');$('#role').value=x.dataset.role;$('#access-code').style.display=isTeam?'block':'none';$('#access-code').required=isTeam;});$('#access-form').onsubmit=e=>{e.preventDefault();$('#access').close();toast('Demo access confirmed. Permitted actions are now available.');};$('#report-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));const result=$('#eco-report-result');if(result){const vals=result.querySelectorAll('span');if(vals[1])vals[1].textContent=`Location: ${data.location||'Hostel A'}`;if(vals[2])vals[2].textContent=`Category: ${data.category||'Other'}`;result.hidden=false;}e.target.reset();toast('Report submitted. The EcoCampus maintenance queue has been notified.');};
document.addEventListener('click',e=>{const action=e.target.closest('[data-eco-action]');if(action){const panel=$('#eco-resolution-panel');const code=action.dataset.ecoAction;if(panel){panel.dataset.ticket=code;panel.dataset.stage='assigned';panel.innerHTML=code==='hostel-ticket'?'<b>Hostel A · Maintenance ticket EC-1042</b><p>Detect ✓ → Assign ✓ → In progress → Awaiting verification</p><button class="eco-progress-action" data-repair-stage="start" data-ticket="hostel">Start repair →</button>':code==='hvac-ticket'?'<b>Academic Block · Electrical Team assigned</b><p>Detect ✓ → Assign ✓ → In progress → Awaiting verification</p><button class="eco-progress-action" data-repair-stage="start" data-ticket="hvac">Start work →</button>':'<b>Cafeteria · Collection ticket EC-1043</b><p>Detect ✓ → Assign ✓ → In progress → Awaiting verification</p><button class="eco-progress-action" data-repair-stage="start" data-ticket="waste">Start collection →</button>';panel.scrollIntoView({behavior:'smooth',block:'center'});}toast('Maintenance ticket added to the command center.');return;}const repair=e.target.closest('[data-repair-stage]');if(repair){const panel=$('#eco-resolution-panel'),ticket=repair.dataset.ticket,stage=repair.dataset.repairStage;if(stage==='start'){panel.dataset.stage='worker';panel.innerHTML=`<b>${ticket==='hostel'?'Hostel A':ticket==='hvac'?'Academic Block':'Cafeteria'} · Repair in progress</b><p>Worker has started the repair. The issue is <strong>not resolved yet</strong>.</p><button class="eco-progress-action" data-repair-stage="worker-confirm" data-ticket="${ticket}">Worker confirms repair complete →</button>`;toast('Repair started. Waiting for worker confirmation.');return;}if(stage==='worker-confirm'){panel.dataset.stage='faculty';panel.innerHTML=`<b>${ticket==='hostel'?'Hostel A':ticket==='hvac'?'Academic Block':'Cafeteria'} · Awaiting faculty verification</b><p>Worker marked the work complete. A faculty/staff verifier must confirm that the issue is actually resolved.</p><button class="eco-progress-action" data-repair-stage="faculty-verify" data-ticket="${ticket}">Faculty verifies resolution →</button>`;toast('Worker confirmation recorded. Faculty verification is required.');return;}if(stage==='faculty-verify'){panel.dataset.stage='resolved';if(ticket==='hostel'){panel.innerHTML='<b>ISSUE RESOLVED ✓</b><p>Hostel A: 1,450 L/day → 820 L/day</p><p>Water usage reduced 43% · Estimated water saved 630 L/day · Estimated monthly saving 18,900 L</p><p>Environmental impact: ↓ Resource waste</p><small>Resolved only after worker confirmation + faculty verification.</small>';}else{panel.innerHTML='<b>ISSUE RESOLVED ✓</b><p>Worker completion was verified by faculty/staff. The maintenance workflow is now closed.</p>';}toast('Issue verified and resolved.');}}});
function bindEcoWhatIf(){const pairs=[['eco-water-range','eco-water-pct','eco-water-save',24600,'L/month'],['eco-energy-range','eco-energy-pct','eco-energy-save',8200,'kWh/month'],['eco-waste-range','eco-waste-pct','eco-waste-save',340,'kg/month']];pairs.forEach(([range,pct,out,base,unit])=>{$('#'+range)?.addEventListener('input',e=>{const v=Number(e.target.value);$('#'+pct).textContent=v+'%';$('#'+out).textContent=Math.round(base*(v/(range==='eco-water-range'?15:range==='eco-energy-range'?10:20)))+' '+unit;});});}bindEcoWhatIf();
async function requestHybridAI(mode,page,question,target){const out=$(target);if(!out)return;out.hidden=false;out.innerHTML='<span class="ai-loading">AI is analyzing the current application context…</span>';try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,page,question,history:[]})});const data=await r.json();if(r.ok&&data.answer){out.innerHTML=`<b>Hybrid AI</b><p>${escOp(data.answer).replace(/\n/g,'<br>')}</p>`;return}}catch(e){}out.innerHTML='<b>Local guidance</b><p>AI service is unavailable, so the built-in application guidance is being used. Try the action controls on this page for the deterministic workflow.</p>';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ai-explain]');if(!b)return;const kind=b.dataset.aiExplain;if(kind==='eco-anomaly')requestHybridAI('eco','insights','Explain the Hostel A water anomaly, likely causes, confidence, recommended action, and how to create and verify the maintenance ticket.','#eco-insight-ai');else if(kind==='eco-forecast')requestHybridAI('eco','insights','Explain the EcoCampus energy forecast for tomorrow 2–4 PM and give the recommended preparation.','#eco-insight-ai');else if(kind==='connect-optimizer')requestHybridAI('connect','c-insights','Explain how the CampusConnect AI Resource Optimizer chooses a best-fit room and what constraints it uses.','#c-insight-ai');else if(kind==='optimizer'){const f=b.closest('.operation-detail-card')?.querySelector('[data-op-form="optimizer"]');const data=f?Object.fromEntries(new FormData(f)):{};requestHybridAI('connect','operations',`Explain this AI Resource Optimizer request and what the recommended room should satisfy: ${JSON.stringify(data)}`,'#optimizer-ai-panel');}});
function currentBotPage(){if(activeDetail)return activeDetail;if(activeView==='connect')return 'connect';if(activeView==='eco')return 'eco';return 'twin';}
const answers={twin:[[/connect|campusconnect|academic|room|timetable|maintenance/i,'CampusConnect handles academic operations: rooms, resources, timetable, maintenance, syllabus progress and AI optimization.'],[/eco|ecocampus|water|energy|waste|sustainability/i,'EcoCampus handles water, energy, waste, eco score, resource anomalies, campus map, AI insights and reporting.'],[/dashboard|how.*use|navigation|page|button/i,'Use the top switcher to enter CampusConnect or EcoCampus. Each system has its own dashboard, map, insights and reporting workflows.']],eco:[[/water|leak|hostel/i,'Hostel A consumes 1,450 L versus an 800 L overnight baseline: an 81% anomaly. Inspect plumbing or unattended outlets immediately.'],[/energy|electric|power/i,'Academic Block is 24% above expected energy use between 2–4 PM. Check HVAC schedules against actual occupancy.'],[/waste|bin|garbage/i,'Cafeteria is 94% full. The suggested collection route is Cafeteria → Hostel A → Library.'],[/report|issue|complaint/i,'To report an EcoCampus issue, open Report issue, enter your college email, choose the location, describe the issue clearly, and submit.'],[/dashboard|use.*dashboard|how.*dashboard/i,'EcoCampus Dashboard shows Water, Energy, Waste and Eco score. Click a metric for its explanation, use the tabs to switch charts, and use the simulation button to test an alert.'],[/map|building/i,'Campus map uses green for stable, yellow for attention and red for critical/anomalous locations. Select a building to inspect its details.'],[/insight|ai/i,'AI insights explain the important resource signals and suggest the next action. Open an insight from the top navigation.'],[/report.*content|what.*report|write.*report/i,'A useful report should include: the exact location, what you observed, when it happened, the affected resource/equipment, severity, and the action you think is needed. Example: “Hostel A, Block A corridor, water is continuously running near the wash area since 6:30 PM; possible leak; please inspect the plumbing.”']],connect:[[/room.*add|add.*room|new.*room/i,'Open Operations → Rooms & resources → Add room. Enter room number, name, category, seats, occupied seats, benches, projector, board, network, status and resources in the pop-up, then choose Add room.'],[/room.*update|update.*room|edit.*room/i,'Open Operations → Rooms & resources. Search or filter the room, review its details, then use the available room-management workflow to update the stored record.'],[/optimizer|best.*room|resource.*optimizer/i,'The AI Resource Optimizer uses student count, time, equipment, network, board and room availability to recommend compatible rooms.'],[/maintenance|issue|repair/i,'Use Maintenance desk to review the issue queue. Reported issues show priority, status, description and room. The form lets authorized users update location, priority, title, category, description, status and worker notes.'],[/report.*issue|how.*report|report.*problem/i,'Open Report issue from the CampusConnect navigation. Enter faculty email, room, priority and a concise description. Submit to notify the maintenance workflow.'],[/report.*content|what.*report|write.*report/i,'A strong CampusConnect issue report should contain: room number, exact equipment/problem, observed symptoms, when it started, impact on teaching, priority, and the requested action. Example: “CSE-103 — projector does not display input during class; issue observed at 10:15; teaching is blocked; High priority; please inspect the projector and cable.”'],[/time|timetable|schedule|clash/i,'Clash-free timetable asks for day, section, start/end time, room and subject. Entries are checked for overlapping local room bookings before saving.'],[/progress|syllabus|coverage/i,'Syllabus progress records subject code, week, coverage percentage, credits and topics covered. Saving a weekly update refreshes the progress summary.'],[/dashboard|occupancy/i,'CampusConnect Dashboard combines rooms available, seat occupancy, open issues and syllabus coverage. Click a metric for its explanation; chart tabs switch between Occupancy, Issues and Coverage.'],[/map|room map/i,'Room map shows five operational spaces. Choose a room from the selector or click a map block to view capacity, occupancy, equipment, status and the recommended next action.'],[/insight|ai insight/i,'AI insights surface maintenance, timetable, syllabus and optimizer signals. Each action button opens the relevant CampusConnect workflow below the operations chooser.'],[/page|navigation|navigate|option|button/i,'Use the CampusConnect navigation for Dashboard, Room map, AI insights, Report issue and Operations. Operation tiles expand directly below the chooser, so you do not lose your place.'],[/how.*use|how.*work/i,'Tell me the operation you are using—Rooms, Maintenance, Timetable, Progress, Optimizer, Dashboard or Room map—and I can explain the steps for that page.']]};
function localBotFallback(question){const page=currentBotPage();const pool=botMode==='twin'?answers.twin:botMode==='eco'?answers.eco:answers.connect;for(const [test,text] of pool)if(test.test(question))return text;if(page==='c-map')return 'You are on Room map. Choose a room from the dropdown or click a map block to inspect capacity, occupancy, equipment, status and the next recommended action.';if(page==='c-dashboard')return 'You are on the CampusConnect dashboard. Use the four metric cards for room availability, occupancy, issues and syllabus coverage; chart tabs show different operational trends.';if(page==='c-report')return 'You are on Report issue. Enter your faculty email, room, priority and a clear description. Include what happened, when, impact and the action needed.';if(page==='c-insights')return 'You are on AI insights. Each card explains an operational signal and its recommended workflow.';if(page==='operations')return 'You are in CampusConnect Operations. Choose Optimizer, Rooms & resources, Maintenance desk, Clash-free timetable or Syllabus progress. The selected workflow opens below the chooser.';if(page==='twin')return 'You are on CampusTwin AI. Ask me what CampusConnect or EcoCampus does, how to navigate, or which page to use for a task.';return botMode==='eco'?'I can help with water, energy, waste, resource scores, the dashboard, map, insights and reporting.':'I can help with rooms, equipment, the optimizer, maintenance, timetable, syllabus progress, dashboard, room map, insights and issue reporting.';}
async function getBotAnswer(question){try{const history=[...document.querySelectorAll('#messages .bot-message')].slice(-8).map(x=>({role:x.classList.contains('you')?'user':'assistant',content:x.textContent}));const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:botMode,page:currentBotPage(),question,history})});const data=await response.json();if(response.ok&&data.answer)return data.answer;}catch(error){}return localBotFallback(question);}
function syncBotVisibility(){const twin=$('#twin-bot-trigger'),connect=$('#connect-bot-trigger'),eco=$('#eco-bot-trigger');const showTwin=activeView==='twin'&&!activeDetail;const showConnect=activeView==='connect'&&!activeDetail;const showEco=activeView==='eco'&&!activeDetail;if(twin)twin.hidden=!showTwin;if(connect)connect.hidden=!showConnect;if(eco)eco.hidden=!showEco;const allowed=(botMode==='twin'&&showTwin)||(botMode==='connect'&&showConnect)||(botMode==='eco'&&showEco);if(!allowed)$('#bot')?.classList.remove('open');}
function openBot(mode){const allowed=(mode==='twin'&&activeView==='twin'&&!activeDetail)||(mode==='connect'&&activeView==='connect'&&!activeDetail)||(mode==='eco'&&activeView==='eco'&&!activeDetail);if(!allowed){$('#bot')?.classList.remove('open');return;}botMode=mode;const bot=$('#bot');if(!bot)return;const names={twin:'CampusTwin AI Guide',connect:'CampusConnect Assistant',eco:'EcoCampus Advisor'};const welcomes={twin:'Hi! I can explain CampusTwin, CampusConnect, EcoCampus, navigation and what each system is for.',connect:'Hi! I can help with this CampusConnect page, rooms, operations, maintenance, timetable, progress, dashboard and issue reporting.',eco:'Hi! I can help with this EcoCampus page, resources, anomalies, dashboard, map, insights and reporting.'};$('#bot-name').textContent=names[mode]||'Campus Guide';const first=$('#messages .bot-message');if(first)first.textContent=welcomes[mode]||welcomes.twin;bot.classList.add('open');setTimeout(()=>$('#bot-input')?.focus(),50);}$$('[data-bot]').forEach(x=>x.addEventListener('click',()=>openBot(x.dataset.bot)));$('.bot-close').onclick=()=>$('#bot').classList.remove('open');$('#bot-form').onsubmit=async e=>{e.preventDefault();const input=$('#bot-input'),q=input.value.trim();if(!q)return;const clean=q.replace(/[<>&]/g,'');$('#messages').insertAdjacentHTML('beforeend',`<p class="bot-message you">${clean}</p><p class="bot-message bot-thinking">Thinking…</p>`);input.value='';$('#messages').scrollTop=$('#messages').scrollHeight;const thinking=$('#messages .bot-thinking:last-child');const reply=await getBotAnswer(q);if(thinking){thinking.classList.remove('bot-thinking');thinking.textContent=reply;}$('#messages').scrollTop=$('#messages').scrollHeight;};

// Initial contextual bot state: exactly one launcher on the three main views, none on detail pages.
syncBotVisibility();
